import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './DoctorDashboard.css';

const DoctorDashboard = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [doctorData, setDoctorData] = useState(null);
  const [appointments, setAppointments] = useState([]);
  const [sharedRecords, setSharedRecords] = useState([]);
  const [patients, setPatients] = useState([]);
  const [prescription, setPrescription] = useState({
    patientId: '',
    medicines: [{ name: '', dosage: '', frequency: '' }],
    notes: ''
  });
  const navigate = useNavigate();

  // Mock data fetch - replace with actual API calls
  useEffect(() => {
    // Fetch doctor data
    const fetchDoctorData = async () => {
      // Replace with actual API call
      const mockDoctor = {
        _id: 'DOC001',
        name: 'Dr. Sarah Johnson',
        specialization: 'Cardiologist',
        experience_years: 12,
        hospital_id: 'HOSP001',
        contact_email: 's.johnson@citygeneral.org',
        phone: '(555) 123-4567'
      };
      setDoctorData(mockDoctor);
      
      // Fetch hospital data
      const mockHospital = {
        _id: 'HOSP001',
        name: 'City General Hospital',
        location: '123 Medical Drive, Cityville',
        contact_email: 'info@citygeneral.org',
        phone: '(555) 987-6543',
        departments: ['Cardiology', 'Pathology', 'Radiology']
      };
      setDoctorData(prev => ({ ...prev, hospital: mockHospital }));
    };

    // Fetch appointments
    const fetchAppointments = async () => {
      // Replace with actual API call
      const mockAppointments = [
        { _id: 'APPT001', patient_id: 'P1001', date: '2025-08-15', time: '10:00 AM', mode: 'In-Person', reason: 'Annual Checkup' },
        { _id: 'APPT002', patient_id: 'P1002', date: '2025-08-15', time: '11:30 AM', mode: 'Online', reason: 'Follow-up' }
      ];
      setAppointments(mockAppointments);
    };

    // Fetch shared records
    const fetchSharedRecords = async () => {
      // Replace with actual API call
      const mockRecords = [
        { _id: 'SHARE001', patient_id: 'P1001', record_type: 'report', record_id: 'REP001', shared_on: '2025-08-10' },
        { _id: 'SHARE002', patient_id: 'P1001', record_type: 'prescription', record_id: 'PRESC001', shared_on: '2025-07-20' }
      ];
      setSharedRecords(mockRecords);
    };

    // Fetch patients
    const fetchPatients = async () => {
      // Replace with actual API call
      const mockPatients = [
        { _id: 'P1001', dob: '1985-03-15', gender: 'Male', timeline_events: ['Annual Checkup 2025', 'Blood Test 2025'] },
        { _id: 'P1002', dob: '1990-07-22', gender: 'Female', timeline_events: ['Follow-up Consultation'] }
      ];
      setPatients(mockPatients);
    };

    fetchDoctorData();
    fetchAppointments();
    fetchSharedRecords();
    fetchPatients();
  }, []);

  const handleLogout = () => {
    // Add logout logic here (clear tokens, etc.)
    navigate('/login');
  };

  const handlePrescriptionChange = (e, index) => {
    const { name, value } = e.target;
    if (index !== undefined) {
      const updatedMedicines = [...prescription.medicines];
      updatedMedicines[index][name] = value;
      setPrescription({...prescription, medicines: updatedMedicines});
    } else {
      setPrescription({...prescription, [name]: value});
    }
  };

  const addMedicineField = () => {
    setPrescription({
      ...prescription,
      medicines: [...prescription.medicines, { name: '', dosage: '', frequency: '' }]
    });
  };

  const removeMedicineField = (index) => {
    const updatedMedicines = prescription.medicines.filter((_, i) => i !== index);
    setPrescription({...prescription, medicines: updatedMedicines});
  };

  const submitPrescription = () => {
    // API call to save prescription
    console.log("Prescription submitted:", prescription);
    alert("Prescription saved successfully!");
    setPrescription({
      patientId: '',
      medicines: [{ name: '', dosage: '', frequency: '' }],
      notes: ''
    });
  };

  if (!doctorData) return <div className="loading">Loading...</div>;

  return (
    <div className="doctor-dashboard">
      {/* Sidebar Navigation */}
      <div className="dashboard-sidebar">
        <div className="sidebar-header">
          <div className="logo-icon">M+</div>
          <h3>MEDIVAULT</h3>
        </div>
        <nav>
          <ul>
            <li 
              className={activeTab === 'dashboard' ? 'active' : ''}
              onClick={() => setActiveTab('dashboard')}
            >
              <i className="fas fa-tachometer-alt"></i> Dashboard
            </li>
            <li 
              className={activeTab === 'patients' ? 'active' : ''}
              onClick={() => setActiveTab('patients')}
            >
              <i className="fas fa-user-injured"></i> View Patients
            </li>
            <li 
              className={activeTab === 'prescriptions' ? 'active' : ''}
              onClick={() => setActiveTab('prescriptions')}
            >
              <i className="fas fa-prescription-bottle-alt"></i> Prescriptions
            </li>
            <li 
              className={activeTab === 'records' ? 'active' : ''}
              onClick={() => setActiveTab('records')}
            >
              <i className="fas fa-file-medical"></i> Shared Records
            </li>
          </ul>
        </nav>
      </div>

      {/* Main Content Area */}
      <div className="dashboard-main">
        {/* Top Bar */}
        <div className="dashboard-topbar">
          <div className="welcome-message">
            <h2>Welcome, <span className="doctor-name">{doctorData.name}</span></h2>
            <p>{doctorData.specialization} at {doctorData.hospital?.name || 'Hospital'}</p>
          </div>
          <div className="topbar-actions">
            <div className="profile-pic" onClick={() => setActiveTab('profile')}>
              {doctorData.name.charAt(0)}
            </div>
            <button className="logout-btn" onClick={handleLogout}>
              <i className="fas fa-sign-out-alt"></i> Logout
            </button>
          </div>
        </div>

        {/* Dashboard Tab */}
        {activeTab === 'dashboard' && (
          <div className="dashboard-content">
            {/* Stats Cards */}
            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-icon">
                  <i className="fas fa-calendar-check"></i>
                </div>
                <div className="stat-value">{appointments.length}</div>
                <div className="stat-label">Today's Appointments</div>
              </div>
              <div className="stat-card">
                <div className="stat-icon">
                  <i className="fas fa-users"></i>
                </div>
                <div className="stat-value">{patients.length}</div>
                <div className="stat-label">Active Patients</div>
              </div>
              <div className="stat-card">
                <div className="stat-icon">
                  <i className="fas fa-file-medical"></i>
                </div>
                <div className="stat-value">{sharedRecords.length}</div>
                <div className="stat-label">Shared Records</div>
              </div>
              <div className="stat-card">
                <div className="stat-icon">
                  <i className="fas fa-prescription-bottle-alt"></i>
                </div>
                <div className="stat-value">24</div>
                <div className="stat-label">Prescriptions This Month</div>
              </div>
            </div>

            {/* Upcoming Appointments */}
            <div className="dashboard-section">
              <h3>Upcoming Appointments</h3>
              <div className="appointments-list">
                {appointments.map(appointment => (
                  <div key={appointment._id} className="appointment-card">
                    <div className="appointment-time">
                      <span className="time">{appointment.time}</span>
                      <span className="mode">{appointment.mode}</span>
                    </div>
                    <div className="appointment-details">
                      <h4>Patient ID: {appointment.patient_id}</h4>
                      <p>{appointment.reason}</p>
                    </div>
                    <button className="action-btn small">
                      <i className="fas fa-eye"></i> View
                    </button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Patients Tab */}
        {activeTab === 'patients' && (
          <div className="dashboard-content">
            <div className="section-header">
              <h3>Patient Records</h3>
              <div className="search-bar">
                <input
                  type="text"
                  placeholder="Search patients by ID..."
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
                <i className="fas fa-search"></i>
              </div>
            </div>
            
            <div className="patients-table">
              <div className="table-header">
                <div>Patient ID</div>
                <div>DOB</div>
                <div>Gender</div>
                <div>Timeline Events</div>
                <div>Actions</div>
              </div>
              
              {patients.map(patient => (
                <div key={patient._id} className="table-row">
                  <div>{patient._id}</div>
                  <div>{patient.dob}</div>
                  <div>{patient.gender}</div>
                  <div className="timeline-events">
                    {patient.timeline_events?.slice(0, 2).map((event, i) => (
                      <span key={i} className="event-tag">{event}</span>
                    ))}
                    {patient.timeline_events?.length > 2 && (
                      <span className="more-events">+{patient.timeline_events.length - 2} more</span>
                    )}
                  </div>
                  <div className="actions">
                    <button className="action-btn small">
                      <i className="fas fa-eye"></i> View Records
                    </button>
                    <button 
                      className="action-btn small primary"
                      onClick={() => {
                        setPrescription({...prescription, patientId: patient._id});
                        setActiveTab('prescriptions');
                      }}
                    >
                      <i className="fas fa-prescription-bottle-alt"></i> Prescribe
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Prescriptions Tab */}
        {activeTab === 'prescriptions' && (
          <div className="dashboard-content">
            <h3>Write New Prescription</h3>
            
            <div className="prescription-form">
              <div className="form-group">
                <label>Select Patient</label>
                <select 
                  name="patientId"
                  value={prescription.patientId}
                  onChange={handlePrescriptionChange}
                  required
                >
                  <option value="">-- Select Patient --</option>
                  {patients.map(patient => (
                    <option key={patient._id} value={patient._id}>
                      {patient._id} ({patient.gender}, {patient.dob})
                    </option>
                  ))}
                </select>
              </div>
              
              <div className="medicines-list">
                <label>Medicines</label>
                {prescription.medicines.map((medicine, index) => (
                  <div key={index} className="medicine-row">
                    <input
                      type="text"
                      name="name"
                      placeholder="Medicine name"
                      value={medicine.name}
                      onChange={(e) => handlePrescriptionChange(e, index)}
                      required
                    />
                    <input
                      type="text"
                      name="dosage"
                      placeholder="Dosage (e.g., 500mg)"
                      value={medicine.dosage}
                      onChange={(e) => handlePrescriptionChange(e, index)}
                      required
                    />
                    <input
                      type="text"
                      name="frequency"
                      placeholder="Frequency (e.g., 2x daily)"
                      value={medicine.frequency}
                      onChange={(e) => handlePrescriptionChange(e, index)}
                      required
                    />
                    {prescription.medicines.length > 1 && (
                      <button 
                        type="button" 
                        className="remove-medicine"
                        onClick={() => removeMedicineField(index)}
                      >
                        <i className="fas fa-times"></i>
                      </button>
                    )}
                  </div>
                ))}
                <button 
                  type="button" 
                  className="add-medicine"
                  onClick={addMedicineField}
                >
                  <i className="fas fa-plus"></i> Add Another Medicine
                </button>
              </div>
              
              <div className="form-group">
                <label>Additional Notes</label>
                <textarea
                  name="notes"
                  value={prescription.notes}
                  onChange={handlePrescriptionChange}
                  placeholder="Enter any additional instructions or notes..."
                  rows="4"
                ></textarea>
              </div>
              
              <div className="form-actions">
                <button 
                  type="button" 
                  className="action-btn secondary"
                  onClick={() => setPrescription({
                    patientId: '',
                    medicines: [{ name: '', dosage: '', frequency: '' }],
                    notes: ''
                  })}
                >
                  Clear Form
                </button>
                <button 
                  type="button" 
                  className="action-btn primary"
                  onClick={submitPrescription}
                  disabled={!prescription.patientId || !prescription.medicines[0].name}
                >
                  <i className="fas fa-save"></i> Save Prescription
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Shared Records Tab */}
        {activeTab === 'records' && (
          <div className="dashboard-content">
            <h3>Shared Medical Records</h3>
            
            <div className="records-filter">
              <select>
                <option value="">All Patients</option>
                {patients.map(patient => (
                  <option key={patient._id} value={patient._id}>
                    {patient._id}
                  </option>
                ))}
              </select>
              <select>
                <option value="">All Record Types</option>
                <option value="report">Reports</option>
                <option value="prescription">Prescriptions</option>
                <option value="file">Files</option>
              </select>
            </div>
            
            <div className="records-list">
              {sharedRecords.map(record => (
                <div key={record._id} className="record-card">
                  <div className="record-header">
                    <h4>Patient ID: {record.patient_id}</h4>
                    <span className="record-type">{record.record_type}</span>
                  </div>
                  <div className="record-details">
                    <span className="record-id">Record ID: {record.record_id}</span>
                    <span className="shared-date">Shared on: {record.shared_on}</span>
                  </div>
                  <div className="record-actions">
                    <button className="action-btn small primary">
                      <i className="fas fa-eye"></i> View Details
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DoctorDashboard;
